    /// <summary>Reads the displacement from the matched instruction. Returns false when the pattern is
    /// missing; a value different from <see cref="OffsetPattern.Analysed"/> is valid (the game patched)
    /// and should be logged, not rejected.</summary>
    public static unsafe bool TryResolve(ISigScanner scanner, OffsetPattern pattern, out int offset)
    {
        offset = 0;
        if (!scanner.TryScanText(pattern.Signature, out var address) || address == nint.Zero)
            return false;
        var at = (byte*)address + pattern.DisplacementIndex;
        offset = pattern.Size == 1 ? *(sbyte*)at : *(int*)at;
        return true;
    }
}

/// <summary>An instruction pattern with a RIP-relative operand that points at a global or vtable.</summary>
internal readonly record struct DataPattern(string Name, string Signature, int RelIndex, int InstructionLength, ulong Analysed);

