    /// <summary>Address the instruction refers to: match + InstructionLength + rel32. A value different from
    /// <see cref="DataPattern.Analysed"/> is normal after a patch.</summary>
    public static unsafe bool TryResolve(ISigScanner scanner, DataPattern pattern, out nint address)
    {
        address = 0;
        if (!scanner.TryScanText(pattern.Signature, out var at) || at == nint.Zero)
            return false;
        address = at + pattern.InstructionLength + *(int*)((byte*)at + pattern.RelIndex);
        return true;
